    _fround(_fround(_fround(v.toDouble()) / 200.0) * 2.0) + -1.0,
  );
  v = (window >>> 8) & 0xff;
  bitsRead += 8;
  if (v > 200) {
    return false; // headroom above the quantum count is refused
  }
  value.aimY = _fround(
    _fround(_fround(_fround(v.toDouble()) / 200.0) * 2.0) + -1.0,
  );
  v = (window >>> 16) & 0xff;
  bitsRead += 8;
  if (v > 200) {
    return false; // headroom above the quantum count is refused
  }
  value.aimZ = _fround(
    _fround(_fround(_fround(v.toDouble()) / 200.0) * 2.0) + -1.0,
  );
  v = (window >>> 24) & 0xffffffff;
  bitsRead += 32;
  value.recoil = _doubleFromFloat32Bits(v);
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0xffffffff;
  bitsRead += 32;
  lo = v;
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0xffffffff;
  bitsRead += 32;
  lo |= v << 32;
  value.drift = _doubleFromFloat64Bits(lo);
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0xffffffff;
  bitsRead += 32;
  lo = v;
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0xffffffff;
  bitsRead += 32;
  lo |= v << 32;
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0xffffffff;
  bitsRead += 32;
  hi = v;
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0xffffffff;
  bitsRead += 32;
  hi |= v << 32;
  value.wideKey = UInt128(hi, lo);
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0xffffffff;
  bitsRead += 32;
  lo = v;
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0xffffffff;
  bitsRead += 32;
  lo |= v << 32;
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0xffffffff;
  bitsRead += 32;
  hi = v;
  v = (window >>> 32) & 0x3f;
  bitsRead += 6;
  hi |= v << 32;
  {
    const diff = UInt128(137438953472, 0);
    if (diff < UInt128(hi, lo)) {
      return false; // a smuggled offset is refused
    }
  }
  {
    const min = UInt128(0xfffffff000000000, 0);
    value.flux = (min + UInt128(hi, lo)).toSigned();
  }
  v = (window >>> 38) & 0xffff;
  bitsRead += 16;
  if (v > 64000) {
    return false; // a smuggled offset is refused
  }
  value.ping = v;
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0xf;
  bitsRead += 4;
  if (v != 0) {
    return false; // reserved bits must read zero (SPEC §4.3)
  }
  {
    final pad = bitsRead & 7;
    if (pad != 0) {
      if (bitsRead + (8 - pad) > numBits) {
        return false;
      }
      if (view.getUint8(bitsRead >>> 3) >>> pad != 0) {
        return false; // nonzero padding is refused (SPEC §4.3)
      }
      bitsRead += 8 - pad;
    }
  }
  if (bitsRead + 25 > numBits) {
    return false;
  }
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0xffffff;
  bitsRead += 24;
  value.crcHint = v;
  v = (window >>> 24) & 0x1;
  bitsRead += 1;
  value.hasExtra = v != 0;
  if (value.hasExtra) {
    if (bitsRead + 8 > numBits) {
      return false;
    }
    if (bitsRead >>> 3 < tailBase) {
      window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
    } else {
      window = tailWord >>> (bitsRead - tailBase * 8);
    }
    v = window & 0xff;
    bitsRead += 8;
    value.extra = v;
    value.idleTicks = 0;
  } else {
    if (bitsRead + 4 > numBits) {
      return false;
    }
    if (bitsRead >>> 3 < tailBase) {
      window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
    } else {
      window = tailWord >>> (bitsRead - tailBase * 8);
    }
    v = window & 0xf;
    bitsRead += 4;
    value.idleTicks = v;
    value.extra = 0;
  }
  return true;
}

// measureBenchMixed is the exact wire bits writeBenchMixed would produce for value —
// trusted like the writer; static runs fold to literals at generation time.
int measureBenchMixed(BenchMixed value) {
  var bits = 0;
  bits += 356;
  bits += value.entitiesCount * 135;
  bits += 7;
  bits += value.statsCount * 18;
  bits += 2;
  switch (value.gameEvent.type) {
    case 1:
      bits += 28;
    case 2:
      bits += 14;
    case 3:
      bits += 18;
  }
  bits += 36;
  bits += (8 - (bits & 7)) & 7;
  bits += value.playerNameLength * 8;
  bits += 5;
  bits += (8 - (bits & 7)) & 7;
  bits += value.payloadLength * 8;
  bits += 370;
  bits += (8 - (bits & 7)) & 7;
  bits += 25;
  if (value.hasExtra) {
    bits += 8;
  } else {
    bits += 4;
  }
  return bits;
}
